INSERT INTO lecciones ("id", "unidad_id", "numero", "titulo", "contenido_teorico", "orden") VALUES
(11, 16, 1, 'Saludos del dia', 'En Quechua, los saludos varian segun el momento del dia. Allillanchu es el saludo mas comun y significa Como estas. La respuesta es Allillanmi (Estoy bien).', 1),
(12, 16, 2, 'Presentaciones personales', 'Para presentarte en Quechua usamos la estructura: Nombre-mi sutiy que significa Mi nombre es.', 2),
(13, 16, 3, 'Despedidas', 'Las despedidas en Quechua: Tupananchikkama - Hasta que nos volvamos a encontrar. Ratukama - Hasta pronto.', 3),
(14, 17, 1, 'Padres y abuelos', 'La familia es el centro de la cultura andina. Tayta (Padre), Mama (Madre), Hatun tayta (Abuelo), Hatun mama (Abuela).', 1),
(15, 17, 2, 'Hermanos e hijos', 'Wawqi (Hermano, dicho por hombre), Turi (Hermano, dicho por mujer), Pani (Hermana, dicho por hombre), Churi (Hijo/a).', 2),
(16, 18, 1, 'Numeros del 1 al 5', 'Huk (1), Iskay (2), Kimsa (3), Tawa (4), Pichqa (5).', 1),
(17, 18, 2, 'Numeros del 6 al 10', 'Suqta (6), Qanchis (7), Pusaq (8), Isqun (9), Chunka (10).', 2),
(18, 19, 1, 'Colores primarios', 'Puka (Rojo), Qillu (Amarillo), Anqas (Azul).', 1),
(19, 19, 2, 'Colores de la naturaleza', 'Qumir (Verde), Yana (Negro), Yuraq (Blanco).', 2),
(20, 20, 1, 'Animales domesticos', 'Llama, Alpaka (Alpaca), Allqu (Perro), Michi (Gato).', 1),
(21, 20, 2, 'Animales silvestres', 'Kuntur (Condor), Puma, Anas (Zorro), Ukuku (Oso andino).', 2),
(22, 21, 1, 'Tuberculos y granos', 'Papa, Sara (Maiz), Kinuwa (Quinua).', 1),
(23, 21, 2, 'Frutas y verduras', 'Pallar (Frijol), Uchu (Aji).', 2),
(90, 39, 1, 'Números grandes 1', 'Números del 11 en adelante: Chunka ujniyuq (once), Chunka iskayniyuq (doce), Chunka kinsayuq (trece), Chunka tawayuq (catorce), Chunka phishqayuq (quince), Chunka suqtayuq (dieciséis), Chunka qanchisniyuq (diecisiete), Chunka pusaqniyuq (dieciocho)…', 1),
(91, 39, 2, 'Números grandes 2', 'Números del 11 en adelante: Iskay chunka iskayniyuq (veintidós), Kinsa chunka (treinta), Tawa chunka (cuarenta), Phishqa chunka (cincuenta), Suqta chunka (sesenta), Qanchis chunka (setenta), Pusaq chunka (ochenta), Isqun chunka (noventa)…', 2),
(92, 39, 3, 'Números grandes 3', 'Números del 11 en adelante: Tawa pachaq (cuatrocientos), Phishqa pachaq (quinientos), Suqta pachaq (seiscientos), Qanchis pachaq (setecientos), Pusaq pachaq (ochocientos), Isqun pachaq (novecientos), Waranqa (mil), Chunka waranqa (diez mil)…', 3),
(93, 40, 1, 'Cantidades 1', 'Cantidades, medidas y formas: Uj ñiqi (primero), Yupay (contar), Yupana (número), Tupuy (medir), Tupu (medida), Iskaynin (ambos), Ch''ulla (impar), Kuskan (mitad)…', 1),
(94, 40, 2, 'Cantidades 2', 'Cantidades, medidas y formas: Ujlla (unidad), Pisi (poco), Ancha (mucho), Ashkha (mucho), Astawan (más), Astawanpis (además), Chhika (tanto), Tumpa (un poco)…', 2),
(95, 40, 3, 'Cantidades 3', 'Cantidades, medidas y formas: Thaski (paso), Thatki (metro), Pachaq wata (siglo), Kinsa k''uchu (triángulo), Tawa k''uchu (cuadrado), Kinsa llimp''iyuq (tricolor), Murq''u (esférico), Muyu (circular)…', 3),
(102, 43, 1, 'El cuerpo 1', 'El cuerpo: Chukcha (cabello), Ñawi (ojo), Ninri (oreja), Sinqa (nariz), Uya (cara), Simi (boca), Kunka (cuello), Qhasqu (pecho)…', 1),
(103, 43, 2, 'El cuerpo 2', 'El cuerpo: Wiksa (barriga), Pupu (ombligo), Maki (mano), Ruk''ana (dedo), Muqu (rodilla), Chaki (pie), Uma (cabeza), Rikra (hombro)…', 2),
(104, 44, 1, 'El cuerpo 1', 'Partes del cuerpo y lo que hacemos con él: Janchi (cuerpo), Lip''ichi (piel), Aycha (carne), Ñik''uta (cabello), Sunkha (barba), T''arwa (vello (del cuerpo)), Ch''ina t''arwa (pelo púbico), Wila (sangre)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 1),
(105, 44, 2, 'El cuerpo 2', 'Partes del cuerpo y lo que hacemos con él: Wich''inkha (cola), Ati (espalda), Jikhani (espinazo), P''iqi (cabeza), Lixwi (cerebro), Ajanu (cara), Para (frente), Änkha (mandíbula)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 2),
(106, 44, 3, 'El cuerpo 3', 'Partes del cuerpo y lo que hacemos con él: Ch''iphuqiña (parpadear), Jinchu (oreja), Nasa (nariz), P''iya (ventana de la nariz), Jurma (moco), Laka (boca), Suru (pico), Ispillu (labio)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 3),
(107, 44, 4, 'El cuerpo 4', 'Partes del cuerpo y lo que hacemos con él: T''ullu (garganta), Kallachi (hombro), Ampara (brazo), Chhiqhanqara (sobaco), Mujlli (codo), Ampara t''axlli (palma de la mano), Luk''ana (dedo), Tayka luk''ana (pulgar)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 4),
(108, 44, 5, 'El cuerpo 5', 'Partes del cuerpo y lo que hacemos con él: Kayu (pie), Kayu muqu (tobillo), Kayu wintu (talón), Kayu luk''ana (dedo del pie), Chhiqha (ala), Phuyu (pluma), Ñuñu (pecho), Kururu (ombligo)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 5),
(109, 44, 6, 'El cuerpo 6', 'Partes del cuerpo y lo que hacemos con él: Jach''a jankhara (bazo), Phatanka (estómago), Jiphilla (intestinos), Ch''illa (cintura), Thixni (cadera), Jakaña (matriz), Aysaña (bostezar), Jik''u (tener hipo)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 6),
(110, 44, 7, 'El cuerpo 7', 'Partes del cuerpo y lo que hacemos con él: Thusaña (escupir (saliva [noun])), Waq''aqiña (vomitar), Achuqaña (morder), Jallq''aña (lamer), Ch''aqaña (gotear), Ikiña (dormir), Qhurqhuña (roncar), Iki (soñar)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 7),
(111, 44, 8, 'El cuerpo 8', 'Partes del cuerpo y lo que hacemos con él: Khathatiña (temblar), Jarisiña (bañar(se)), Katuña (engendrar), Yuriña (nacer), Wallq''i (embarazada (mujer)), Jiwata (morir), Amaya (cadáver), Imantaña (sepultar)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 8),
(112, 44, 9, 'El cuerpo 9', 'Partes del cuerpo y lo que hacemos con él: Usuta (enfermo), Chhujchhu (fiebre), Q''utu (bocio), Usuchata (herida), P''usu (hinchazón), Jasi (comezón), Pukullu (ampolla), Jinq''i (furúnculo)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 9),
(113, 44, 10, 'El cuerpo 10', 'Partes del cuerpo y lo que hacemos con él: Qulla (medicina), Qarita (cansado), Samaraña (descansar), Jayra (perezoso), Q''ara (calvo), Wixchu (lisiado), Uqara (sordo), Amutu (mudo)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 10),
(114, 45, 1, 'La familia 1', 'Familia y parentesco: Jaqi (persona), Chacha (hombre), Warmi (mujer), Urqu (varón), Qachu (hembra), Majt''a (muchacho), Wayna (el joven), Imilla (muchacha)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 1),
(115, 45, 2, 'La familia 2', 'Familia y parentesco: Jaqi chasiwi (casamiento), Jarjtaña (divorcio), Awki (padre), Tayka (madre), Awki naka (padres), Warmina jaqi (hombre casado), Chachani warmi (mujer casada), Yuqa (hijo)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 2),
(116, 45, 3, 'La familia 3', 'Familia y parentesco: Sullkiri jila (hermano menor), Kullaka (hermana), Jilïri kullaka (hermana mayor), Sullkiri kullaka (hermana menor), Ispa (gemelos), Achila (abuelo), Awki jaqi (hombre viejo), Awicha (abuela)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 3),
(117, 45, 4, 'La familia 4', 'Familia y parentesco: Tiwula (tío), Ipata (tía), Jilata (primo), Achachila (antepasados), Awkch''i (suegro (de hombre)), Taykch''i (suegra (de hombre)), Tullqa (yerno (de hombre)), Yujch''a (nuera (de hombre))… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 4),
(118, 45, 5, 'La familia 5', 'Familia y parentesco: Iñu (huérfano), Ijma (viuda), Uta (familia), Naya (yo), Juma (tú), Jupa (él), Nanaka (nosotros), Jiwasa (nosotros)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 5),
(119, 46, 1, 'Los animales 1', 'Animales domésticos y silvestres: Uywa (animal), Awatiri (pastor), Uyu (establo), Puytu (oveja), Khuchi (puerca), Jamach''i (ave (de corral)), K''ank''a (gallo), Wallpa (gallina)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 1),
(120, 46, 2, 'Los animales 2', 'Animales domésticos y silvestres: Tapa (nido), Paka (águila), Mamani (gavilán), Siwiq''ara (buitre), Chiñi (murciélago), K''alla (loro), Urpila (paloma), Ch''usiqa (lechuza)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 2),
(121, 46, 3, 'Los animales 3', 'Animales domésticos y silvestres: Phisi (gato), Achupalla (zarigüeya), Achaku (ratón), Chawlla (pez), Lluxi (escama), Liwuna (león), Jukumari (oso), Qamaqi (zorro)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 3),
(122, 46, 4, 'Los animales 4', 'Animales domésticos y silvestres: Laq''u (insecto), Lap''a (piojo), Ch''iñi (liendre), K''uti (pulga), Warisana (ciempiés), K''usiwallu (hormiga), Kusi kusi (araña), Llika (telaraña)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 4),
(123, 46, 5, 'Los animales 5', 'Animales domésticos y silvestres: Pankataya (avispa), Chhichhillankha (mosca), Ch''uspi (jején), Sillq''u (lombriz), Asiru (culebra), Pilpintu (mariposa), T''iju t''iju (saltamontes), Ch''uru (caracol)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 5),
(124, 47, 1, 'Comida 1', 'Alimentos, cocina y bebidas: Manq''aña (comer), Manq''a (comida), Phayata (cocido), Ch''uqi (crudo), Puquta (maduro), Ch''uxña (inmaduro), Ñusata (podrido), Umaña (beber)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 1),
(125, 47, 2, 'Comida 2', 'Alimentos, cocina y bebidas: Khisthuña (masticar), Mallxtayaña (tragar), Phayaña (cocinar), Wallaqiña (hervir), Kankaña (asar), Phukhu (olla), Chatu (caldera), Chuwa (plato)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 2),
(126, 47, 3, 'Comida 3', 'Alimentos, cocina y bebidas: Sillp''iraña (pelar), Susuña (cribar), Khithuña (raspar), Thikhiña (mezclar), T''ant''a (pan), Chapuña (amasar), Jak''u (harina), Sillp''jaña (aplastar)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 3),
(127, 47, 4, 'Comida 4', 'Alimentos, cocina y bebidas: Muxsächu (fruta), Iwusa (higo), Uwasa (uva), Jayu (sal), Wayk''a (ají), Misk''i (miel), Millk''i (leche), Ch''awaña (ordeñar)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 4),
(128, 48, 1, 'La casa 1', 'La casa y sus partes: Utjaña (habitar), Chhujilla (cabaña), Utänqa (cancha), Punku (puerta), T''uxu (ventana), Pirqa (pared), Qhiri (fogón). Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 1),
(129, 48, 2, 'La casa 2', 'La casa y sus partes: Patill patilla (escalera), Patät''i (cama), Ch''ijmaña (almohada), Qunuña (silla), Lamana (batea), Wichhu jichhu (paja (para techumbre)), Lawa (viga). Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 2),
(130, 49, 1, 'Ropa y tejidos 1', 'Vestimenta, tejidos y adornos: Isisiña (vestirse), Isi (ropa), Ch''ukuri (sastre), Qhiya (algodón), Qapuña (hilar), Qapu (huso), Sawuña (tejer), Ch''ukuña (coser)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 1),
(131, 49, 2, 'Ropa y tejidos 2', 'Vestimenta, tejidos y adornos: Junuña (punzón), Ch''ankha (hilo), Samachaña (teñir), Yaqhulla (capa), Punchu (poncho), Kuyllu (cuello), P''ullqu (zapato), Tanka (sombrero)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 2),
(132, 49, 3, 'Ropa y tejidos 3', 'Vestimenta, tejidos y adornos: K''achacha (adorno), Chipana (brazalete), Ajuña (collar), Wallqa (chaquira), Sanu (peine), K''anaña (trenzar), Qaquntaña (ungüento), Lirphu (espejo). Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 3),
(133, 50, 1, 'La naturaleza 1', 'Tierra, agua, cielo y fuego: Uraqi (tierra), Laq''a (polvo), Ñiq''i (lodo), Ch''alla (arena), Qullu (montaña), Pampa (pampa), Qhirwa (valle), Quta laka (ribera)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 1),
(134, 50, 2, 'La naturaleza 2', 'Tierra, agua, cielo y fuego: Mama quta (océano), Quta (lago), Qutaña (laguna), Uji (ola), Jawira (río), Phuch''u (manantial), Phusu (pantano), Phajcha (cascada)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 2),
(135, 50, 3, 'La naturaleza 3', 'Tierra, agua, cielo y fuego: Qala (piedra), Alaj pacha (cielo), Inti (sol), Phajsi (luna), Wara wara (estrella), Q''iju q''iju (relámpago), Lliju lliju (rayo), Wayra (tempestad)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 3),
(136, 50, 4, 'La naturaleza 4', 'Tierra, agua, cielo y fuego: Ch''amaka (oscuridad), Ch''iwi (sombra), Sulla (rocío), Thaya (viento), Qinaya (nube), Urpu (neblina), Jallu (lluvia), Khunu (nieve)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 4),
(137, 50, 5, 'La naturaleza 5', 'Tierra, agua, cielo y fuego: Laphaqi (llama), Jiq''i (humo), Qhilla (cenizas), Sank''a (brasas), Phichhaña (quemar), Nakhaña (arder), Naktaña (encender), Jiwaqayaña (apagar)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 5),
(138, 51, 1, 'Números 1', 'Contar y medir: Ch''usa (cero), Maya (uno), Paya (dos), Kimsa (tres), Pusi (cuatro), Phisqa (cinco), Suxta (seis), Paqallqu (siete)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 1),
(139, 51, 2, 'Números 2', 'Contar y medir: Tunka mayani (once), Tunka payani (doce), Tunka phisqani (quince), Pätunka (veinte), Pataka (ciento), Waranqa (mil), Jakhuña (contar), Sapa (cada uno)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 2),
(140, 51, 3, 'Números 3', 'Contar y medir: Walja (bastante), Walkha (un poco), Phuqa (lleno), Chikata (mitad), Sapaki (solo), Nayrïri (primero), Qhipïri (último), Payïri (segundo)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 3),
(141, 52, 1, 'El tiempo 1', 'Días, estaciones y momentos:  pacha (tiempo), Wiña (edad), Machaqa (nuevo), Llullu (tierno), Achachi (viejo), Arumirja (temprano), Jayp''u (tarde), Jichha (ahora)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 1),
(142, 52, 2, 'El tiempo 2', 'Días, estaciones y momentos: Qhipharaña (demorar), Qalltaña (empezar), Tuku (fin), Tukuña (acabar),  puni (siempre), Jayapacha (por mucho tiempo), Mämpi (otra vez), Uru (día)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 2),
(143, 52, 3, 'El tiempo 3', 'Días, estaciones y momentos: Chika uru (mediodía), Jichhüru (hoy), Jurpanmanthi (pasado mañana), Wasuru (ayer), Walüru (anteayer), Phaxsi (mes), Mara (año), Thäpacha (invierno)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 3),
(144, 53, 1, 'Lugares 1', 'Dónde están las cosas: Ukata (después), Qhipäxa (atrás), Aynacha (abajo), Nayraqata (delante), Manqha (adentro), Anqa (afuera), Manqhata (debajo), Amta (arriba)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 1),
(145, 53, 2, 'Lugares 2', 'Dónde están las cosas: Ikintxaña (acostarse), Sayt''aña (poner(se) de pie), Qhipaqtaña (quedar), Jilt''a (sobras), Apthapiña (recoger), Qullucht''a (amontonar), Apjaña (separar), Lakjaña (dividir)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 2),
(146, 53, 3, 'Lugares 3', 'Dónde están las cosas: Alaya (alto), Ch''utu (cima), Tukuya (final), Yärata (puntiagudo), Thiya (lado), Taypi (medio), Kupi (derecha), Ch''iqa (izquierda)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 3),
(147, 53, 4, 'Lugares 4', 'Dónde están las cosas: Jalanta (oeste), Amsta (norte), Jilaña (crecer), Luqa (braza (medida)), Jach''a (grande), Jisk''a (chico), Waru (largo), Araxa (alto)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 4),
(148, 53, 5, 'Lugares 5', 'Dónde están las cosas: Juch''usa (delgado), Pataki (bajo), Chiqa (derecho), Millk''uta (torcido), K''uchu (esquina), Chakana (cruz), Muruq''u (redondo), Siqi (línea)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 5),
(149, 54, 1, 'Los sentidos 1', 'Ver, oír, tocar; colores y formas: Mukhiña (oler), Thujsa (hediondo), Muxsa (dulce), Jayuk''ara (salado), Jaxu (amargo), K''allk''u (ácido), Ist''aña (oír), Isch''ukiña (escuchar)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 1),
(150, 54, 2, 'Los sentidos 2', 'Ver, oír, tocar; colores y formas: Uñjaña (ver), Uñtaña (mirar), Uñacht''ayaña (mostrar), Qhanaña (brillar), Qhaniri (brillante), Sami (color), Janq''u (blanco), Ch''iyara (negro)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 2),
(151, 54, 3, 'Los sentidos 3', 'Ver, oír, tocar; colores y formas: Q''illu (amarillo), Llamkht''aña (tocar), K''ichiña (pellizcar), Ch''ullqhi (duro), Jasa (suave), Chhankha (áspero), Quña (suave), Ari (afilado)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 3),
(152, 54, 4, 'Los sentidos 4', 'Ver, oír, tocar; colores y formas: Phisna (liviano), Ch''arana (mojado), Waña (seco), Junt''u (caliente), Achhiju (tibio), Alala (frío), Q''uma (limpio), Q''añu (sucio)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 4),
(153, 55, 1, 'Moverse 1', 'Ir, venir, caminar y viajar: Unxtaña (mover), Jaqukipaña (volcar), Llawuña (enrollar), Qurumiña (rodar), Millk''uña (torcer), Makataña (ascender), Aptaña (levantar), Tinkuña (caer)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 1),
(154, 55, 2, 'Moverse 2', 'Ir, venir, caminar y viajar: Jalaña (fluir), Jununtaña (hundir), Tuyuña (flotar), Ch''itiqkataña (salpicar), Wiruña (volar), Phusaña (soplar), Kumptaqaña (gatear), Killt''asiña (arrodillarse)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 2),
(155, 55, 3, 'Moverse 3', 'Ir, venir, caminar y viajar: Takiña (patear), Thuquña (bailar), Saraña (caminar), Wixchiña (lisiar), T''ijuña (correr), Warkkattaña (trepar), Maqaña (bajar), Mistuña (salir)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 3),
(156, 55, 4, 'Moverse 4', 'Ir, venir, caminar y viajar: T''ijumuchuña (huir), Arkaña (seguir), Arknaqaña (perseguir), Jikjataña (llegar), Jak''achaña (acercarse), Mantaña (entrar), Apaña (llevar), Q''ipiña (llevar a la espalda)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 4),
(157, 55, 5, 'Moverse 5', 'Ir, venir, caminar y viajar: Sarayaña (conducir), Lat''aña (montar), Nukhuña (empujar), Thakhi (carretera), Chaka (puente), Muyu (rueda), Wampu (bote), Yampu (canoa)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 5),
(158, 56, 1, 'Trabajos 1', 'Acciones del trabajo y sus herramientas: Luraña (hacer), Q''iwiña (encorvar), Q''iwt''aña (doblar), Ñach''aña (amarrar), Jararaña (desatar), Wiska (cuerda), Muqu (nudo), Liq''iña (golpear)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 1),
(159, 56, 2, 'Trabajos 2', 'Acciones del trabajo y sus herramientas: Q''alluña (tajar), P''akiña (quebrar), P''akita (quebrado), Jaljaña (hender), Ch''iyjaña (romper), Kharsuña (desollar), Qaquña (frotar), Iqatataña (alargar)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 2),
(160, 56, 3, 'Trabajos 3', 'Acciones del trabajo y sus herramientas: Q''aphiña (apretar), Q''apthapiña (estrujar), Q''upthapiña (vaciar), Jariña (lavar), Pichaña (barrer), Pirqaña (edificar), P''iyantaña (perforar), Qaqantaña (ahuecar)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 3),
(161, 56, 4, 'Trabajos 4', 'Acciones del trabajo y sus herramientas: K''awsi (cobre), Malla (plomo), Chayanta (estaño), Ñiwk''i (barro), Qhispi (vidrio), Sawaña (tejer), Sixi (estera), Jant''aku (tapete)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 4),
(162, 57, 1, 'La chacra 1', 'Agricultura y plantas: Yapuchiri (labrador), Yapu (campo (de cultivo)), Yapuchaña (cultivar), Larqa (zanja), Qhulliña (arar), Phat''suña (excavar), Sataña (sembrar), Jatha (semilla)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 1),
(163, 57, 2, 'La chacra 2', 'Agricultura y plantas: Muchhaña (trillar), P''iraña (era), Apthapi (cosecha), Tunqu (maíz), Qura (hierba), Ali (planta), Saphi (raíz), Laymi (rama). Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 2),
(164, 57, 3, 'La chacra 3', 'Agricultura y plantas: Laphi (hoja), Panqara (flor), Thujsa thujsa (tabaco), P''allqa (rama bifurcada), Yuka (mandioca), Suq''usa (bambú), Itapallu (ortiga), Sirk''i (hongo). Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 3),
(165, 58, 1, 'Tener y compartir 1', 'Posesión, compra y venta: Jikiña (obtener), Imaña (conservar), Yä (cosa), Churaña (dar), Kutiyaña (devolver), Jark''aña (conservar), Qhispiyaña (salvar), Tukjaña (destruir)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 1),
(166, 58, 2, 'Tener y compartir 2', 'Posesión, compra y venta: Jikxataña (encontrar), Chhaqaña (perder), Antutaña (soltar), Qamiri (rico), T''aqhi (pobre), Mich''a (avaro), Mayt''aña (prestar), Mayt''asiña (pedir prestado)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 2),
(167, 58, 3, 'Tener y compartir 3', 'Posesión, compra y venta: Manu (deuda), Alaña (comprar), Aljaña (vender), Alakipa (comerciante), Qhatu (mercado), Chani (precio), Iraqata (barato), Lakiña (repartir)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 3),
(168, 59, 1, 'Sentimientos 1', 'Emociones y valores: Ajayu (alma), Kusisita (alegre), Laruña (reír), Anataña (jugar), Munaña (querer), Jamp''atiña (besar), Wallq''iptaña (abrazar), Llaki (tristeza)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 1),
(169, 59, 2, 'Sentimientos 2', 'Emociones y valores: Jachaña (llorar), Jacha (lágrima), K''añaña (gemir), Uñisiña (odiar), Jachjaña (enojo), P''inqa (vergüenza), Axsaraña (miedo), Chiji (peligro)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 2),
(170, 59, 3, 'Sentimientos 3', 'Emociones y valores: K''arisiña (mentir), Pampachaña (perdonar), Suma (bueno), Qhuru (malo), Jucha (culpa), Pantaña (equivocación), K''acha (hermoso), Axtaña (feo)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 3),
(171, 60, 1, 'Pensar 1', 'La mente y el saber: Amuyu (mente), Lup''iña (pensar), Amuyaña (entender), Yatiña (saber), Jamuña (adivinar), Yatxapayaña (imitar), Amawt''a (sabio), Ipi (necio)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 1),
(172, 60, 2, 'Pensar 2', 'La mente y el saber: Yatiqiri (alumno), Yatichiri (profesor), Yatiñuta (escuela), Amtaña (recordar), Armaña (olvidar), Imantata (secreto), Yaticht''aña (explicar), Sallqjaña (traicionar)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 2),
(173, 60, 3, 'Pensar 3', 'La mente y el saber: Jïsa (sí), Janiwa (no), Kumasa (¿cómo?), Qawqhanaksa (¿cuántos?), Qawqhsa (¿cuánto?), Kunasa (¿qué?), Kunarsa (¿cuándo?), Kawkinsa (¿dónde?)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 3),
(174, 61, 1, 'Hablar 1', 'Decir, preguntar y contar: Aru (voz), Jaylliña (cantar), Arnaqaña (gritar), Jinchuru arxayaña (cuchichear), Khuyuña (silbar), Aruña (hablar), Khakhaña (tartamudear), Saña (decir)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 1),
(175, 61, 2, 'Hablar 2', 'Decir, preguntar y contar: Arst''aña (pronunciar un discurso), Amukt''aña (callarse), Suti (nombre), Jiskhiña (preguntar), Jaysaña (contestar), Janichaña (negar), Mayiña (pedir), Jawsaña (llamar). Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 2),
(176, 61, 3, 'Hablar 3', 'Decir, preguntar y contar: Jawsasiña (llamarse), Yatiyaña (anunciar), Qillqaña (escribir), Uñaña (leer), Panka (libro), Yarqwiku (poeta), Qina (flauta), Wankara (bombo). Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 3),
(177, 62, 1, 'La comunidad 1', 'Sociedad, normas y creencias: Marka (país), Qurpa (límite), Marka chiri (pueblo), Kuraka (jefe), Thujru (bastón), Quya (reina), Iyawäña (obedecer), Ya (permitir)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 1),
(178, 62, 2, 'La comunidad 2', 'Sociedad, normas y creencias: Qurpachuta (huésped), Yanapaña (ayudar), Ch''axwa (lucha), Nuwasiña (pelear), Palla palla (soldado), Q''urawa (honda), Mich''i (flecha), Pukara (fortaleza)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 2),
(179, 62, 3, 'La comunidad 3', 'Sociedad, normas y creencias: Lik''i (cebo), Sipita (trampa), Katjaña (atrapar), Kamachi (ley), Taripaña (juzgar), Taripiri (juez), Tumpiri (demandante), Tumpata (acusado)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 3),
(180, 62, 4, 'La comunidad 4', 'Sociedad, normas y creencias: Juchani (culpable), Lunthataña (robar), Lunthata (ladrón), Pachamama (Dios), Luqta (ofrenda), Qulläna (sagrado), Nanqhaña (maldecir), Alaxpacha (cielo)… Vocabulario de Félix Layme Pairumani en el Intercontinental Dictionary Series (CC BY 4.0).', 4)
