INSERT INTO contenido_cultural ("id", "tipo", "idioma", "titulo", "contenido_original", "traduccion", "audio_url", "imagen_url", "created_at", "updated_at", "explicacion", "autor", "region", "dificultad", "tags", "vistas") VALUES
(1, 'adivinanza', 'quechua', 'El ojo', 'Huk huchuy qucha, mana yaku chinkayniyuq. ¿Iman?', 'Un pequeño lago que nunca se seca. ¿Qué es?', NULL, NULL, '2025-12-27T05:00:17.718Z', '2025-12-27T05:00:17.718Z', 'Respuesta: Ñawi (El ojo). Esta adivinanza usa la metáfora del agua para describir el brillo del ojo.', NULL, 'Cusco', 'basico', ARRAY['adivinanza', 'cuerpo', 'ojo']::text[], 0),
(2, 'adivinanza', 'quechua', 'La lengua', 'Huk ukupi tiyaq, mana chaki, mana maki, ichaqa kuyuq. ¿Iman?', 'Vive adentro, no tiene pies ni manos, pero se mueve. ¿Qué es?', NULL, NULL, '2025-12-27T05:00:17.718Z', '2025-12-27T05:00:17.718Z', 'Respuesta: Qallu (La lengua). Describe la lengua como algo que vive en la boca y se mueve sin extremidades.', NULL, 'Puno', 'basico', ARRAY['adivinanza', 'cuerpo', 'lengua']::text[], 0),
(3, 'adivinanza', 'quechua', 'El huevo', 'Yuraq wasichapi huk quri qucha. ¿Iman?', 'En una casa blanca hay un lago dorado. ¿Qué es?', NULL, NULL, '2025-12-27T05:00:17.718Z', '2025-12-27T05:00:17.718Z', 'Respuesta: Runtu (El huevo). La casa blanca es la cáscara y el lago dorado es la yema.', NULL, 'Ayacucho', 'basico', ARRAY['adivinanza', 'comida', 'huevo']::text[], 0),
(4, 'adivinanza', 'quechua', 'El maíz', 'Huk mamitapa wawankuna, tukuy quri pachayuq. ¿Iman?', 'Los hijos de una mamita, todos con ropa dorada. ¿Qué es?', NULL, NULL, '2025-12-27T05:00:17.718Z', '2025-12-27T05:00:17.718Z', 'Respuesta: Sara (El maíz). Los granos son los hijos y su color amarillo es la ropa dorada.', NULL, 'Cusco', 'intermedio', ARRAY['adivinanza', 'comida', 'maiz']::text[], 0),
(5, 'adivinanza', 'quechua', 'La estrella', 'Tutapi rikukun, punchawpi chinkan. ¿Iman?', 'De noche se ve, de día desaparece. ¿Qué es?', NULL, NULL, '2025-12-27T05:00:17.718Z', '2025-12-27T05:00:17.718Z', 'Respuesta: Quyllur (La estrella). Las estrellas solo son visibles en la noche.', NULL, 'Andes', 'basico', ARRAY['adivinanza', 'cielo', 'estrella']::text[], 0),
(6, 'proverbio', 'quechua', 'No seas ladrón', 'Ama suwa, ama llulla, ama qilla.', 'No seas ladrón, no seas mentiroso, no seas ocioso.', NULL, NULL, '2025-12-27T05:00:17.718Z', '2025-12-27T05:00:17.718Z', 'Los tres principios fundamentales del Imperio Inca que guiaban la conducta moral de los ciudadanos.', NULL, 'Cusco', 'basico', ARRAY['proverbio', 'moral', 'inca']::text[], 0),
(7, 'proverbio', 'quechua', 'La unión hace la fuerza', 'Hukllachu kaspa, tukuy ima atipasunmi.', 'Estando unidos, todo lo podemos.', NULL, NULL, '2025-12-27T05:00:17.718Z', '2025-12-27T05:00:17.718Z', 'Refleja el valor de la comunidad y el trabajo colectivo en la cultura andina.', NULL, 'Andes', 'basico', ARRAY['proverbio', 'comunidad', 'union']::text[], 0),
(8, 'proverbio', 'quechua', 'El trabajo', 'Llamk''aqpaqqa mikhuyqa mana pisipanchu.', 'Para el que trabaja, la comida nunca falta.', NULL, NULL, '2025-12-27T05:00:17.718Z', '2025-12-27T05:00:17.718Z', 'Enseña el valor del trabajo como medio para asegurar el sustento.', NULL, 'Puno', 'intermedio', ARRAY['proverbio', 'trabajo', 'comida']::text[], 0),
(9, 'proverbio', 'quechua', 'La sabiduría', 'Yachaqqa mana ñanpi chinkanchu.', 'El que sabe no se pierde en el camino.', NULL, NULL, '2025-12-27T05:00:17.718Z', '2025-12-27T05:00:17.718Z', 'Destaca la importancia del conocimiento como guía en la vida.', NULL, 'Ayacucho', 'intermedio', ARRAY['proverbio', 'sabiduria', 'conocimiento']::text[], 0),
(10, 'proverbio', 'quechua', 'El respeto', 'Mayqin runatapas yupaychay, qamtapas yupaychasunkim.', 'Respeta a cualquier persona, y te respetarán a ti.', NULL, NULL, '2025-12-27T05:00:17.718Z', '2025-12-27T05:00:17.718Z', 'Principio de reciprocidad aplicado al respeto mutuo.', NULL, 'Cusco', 'basico', ARRAY['proverbio', 'respeto', 'reciprocidad']::text[], 0),
(11, 'cancion', 'quechua', 'Valicha', 'Valichay, Valichay, imatan ruwachkanki
